/// USACO-style scoring: one 10-point subtask per case.
List<Subtask>? usacoSubtasks(String id) {
  if (!id.startsWith('ub') && !id.startsWith('ue')) return null;
  return [
    for (var i = 0; i < 10; i++)
      Subtask(
          points: 10,
          labelEs: 'Caso ${i + 1}',
          labelEn: 'Case ${i + 1}',
          tests: [i]),
  ];
}
